/* SEED */
const $=s=>document.querySelector(s);
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHTML;
const paths={
  overview:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',
  city:'<path d="M3 21h18M5 21V7l7-4v18M12 10l7-3v14M8 9v1m0 3v1m0 3v1m8-7v1m0 3v1"/>',
  jobs:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12l9 4 9-4m-9 4v3"/>',
  market:'<path d="M3 10h18L19 4H5l-2 6ZM4 10v11h16V10M8 21v-7h5v7M3 10c0 4 4 4 4 0 0 4 5 4 5 0 0 4 5 4 5 0 0 4 4 4 4 0"/>',
  housing:'<path d="m3 10 9-7 9 7v11H3V10Zm6 11v-8h6v8"/>',
  underground:'<path d="M5 7h14l2 10-9 4-9-4L5 7Zm0 0 4-4h6l4 4M7 12h2m6 0h2m-8 5h6"/>',
  institutions:'<path d="m3 7 9-4 9 4H3Zm2 3v8m5-8v8m4-8v8m5-8v8M3 21h18M2 18h20"/>',
  citizens:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M16 4a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5v2"/>',
  user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',
  coin:'<circle cx="12" cy="12" r="9"/><path d="M15 8h-4a2 2 0 0 0 0 4h2a2 2 0 0 1 0 4H9m3-10v2m0 8v2"/>',
  health:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8ZM3 11h5l2-3 4 8 2-5h5"/>',
  energy:'<path d="m13 2-9 12h7l-1 8 10-12h-7l0-8Z"/>',
  temp:'<path d="M9 14.8V5a3 3 0 0 1 6 0v9.8a5 5 0 1 1-6 0ZM12 8v10m7-12h2m-2 4h2"/>',
  bread:'<path d="M5 10C0 9 1 3 7 3h10c6 0 7 6 2 7v10H5V10Zm4-3 1 3m4-3 1 3"/>',
  soup:'<path d="M3 13h18a9 9 0 0 1-18 0ZM8 3c-4 4 4 4 0 8m5-8c-4 4 4 4 0 8m5-8c-4 4 4 4 0 8M5 22h14"/>',
  coat:'<path d="m8 3-5 4-2 8 4 2 1-7v11h12V10l1 7 4-2-2-8-5-4-4 5-4-5Zm4 5v13"/>',
  box:'<path d="m3 7 9-4 9 4v10l-9 4-9-4V7Zm0 0 9 5 9-5m-9 5v9M7 5l9 5"/>',
  warning:'<path d="m12 3 10 18H2L12 3Zm0 6v5m0 3h.01"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
  pin:'<path d="M19 9c0 5-7 12-7 12S5 14 5 9a7 7 0 0 1 14 0Z"/><circle cx="12" cy="9" r="2"/>',
  cloud:'<path d="M7 17H6a4 4 0 1 1 1-8 6 6 0 0 1 11-2 5 5 0 1 1 0 10H7Zm-2 4h14"/>',
  shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Zm-4 8 3 3 5-6"/>',
  help:'<circle cx="12" cy="12" r="9"/><path d="M9 8a3 3 0 0 1 6 1c0 2-3 2-3 4m0 4h.01"/>',
  close:'<path d="m6 6 12 12M6 18 18 6"/>',
  menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',
  union:'<path d="M6 21V9h3V4h3v5h3V6h3v8l-3 7H6Zm0-8-3-3v7l3 4"/>',
  lock:'<rect x="5" y="10" width="14" height="12" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v3"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
};
const icon=(name,cls='')=>`<svg viewBox="0 0 24 24" class="${cls}" aria-hidden="true">${paths[name]||paths.box}</svg>`;
const tabs=[['overview','Overview'],['street','Short tasks'],['workshop','Workshop'],['network','Neural network'],['city','The city'],['jobs','Find work'],['market','Marketplace'],['housing','Housing'],['loadout','Loadout'],['inventory','Inventory'],['careers','Careers'],['encounters','Your story'],['forces','Order & Chaos'],['underground','Underground'],['institutions','Institutions'],['citizens','Citizens']];
let state=SEED,ready=false,busy=false,tab=location.hash.slice(1)||'overview',filter='all',marketTab='supply',connection='',toastTimer,pendingAction=null,storyTab='encounters';
const drafts={notice:'',name:''};
const timeAgo=t=>{const m=Math.floor((Date.now()-t)/60000);return m<1?'JUST NOW':m<60?`${m}M AGO`:m<1440?`${Math.floor(m/60)}H AGO`:`${Math.floor(m/1440)}D AGO`;};
const c=()=>state.citizen;
const button=(label,action,id='',cls='',disabled=false,attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${id?`data-id="${e(id)}"`:''} ${disabled||busy||c().activity&&['work','rest','crime','rite','organize','clinic','official_work','business_work','security_work','event_work','clearance','career','career_claim'].includes(action)?'disabled':''} ${attrs}>${label}</button>`;
const navButton=(label,dest,cls='btn ghost')=>`<button class="${cls}" data-nav="${dest}">${label}</button>`;
function heading(title,description){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div><div class="location-tag">${icon('pin')} NINTH STRATUM</div></div>`;}
function stats(){const p=c();return `<div class="stats"><div class="stat gold"><div class="stat-top">${icon('coin')} CREDITS</div><div class="stat-value">${p.credits}<small>CR</small></div><div class="stat-bottom"><span>Available balance</span><span>${p.rentDebt>p.credits?'<span class="low">Rent shortfall</span>':'Keep it close'}</span></div></div><div class="stat ${p.health<30?'warn':''}"><div class="stat-top">${icon('health')} HEALTH</div><div class="stat-value">${Math.round(p.health)}<small>/ 100</small></div><div class="stat-bottom"><span>${p.health<30?'In bad shape':p.health<70?'Worn down':'Holding together'}</span><span>VITALS</span></div><div class="progress"><span style="width:${Math.round(p.health)}%"></span></div></div><div class="stat ${p.energy<25?'warn':''}"><div class="stat-top">${icon('energy')} ENERGY</div><div class="stat-value">${Math.round(p.energy)}<small>/ 100</small></div><div class="stat-bottom"><span>${p.energy<25?'Exhausted':'Fit for another shift'}</span><span>STAMINA</span></div><div class="progress"><span style="width:${Math.round(p.energy)}%"></span></div></div><div class="stat ${p.warmth<35?'warn':''}"><div class="stat-top">${icon('temp')} WARMTH</div><div class="stat-value">${Math.round(p.warmth)}<small>/ 100</small></div><div class="stat-bottom"><span class="${p.warmth<35?'low':''}">${p.warmth<15?'Freezing':p.warmth<35?'Cold to the bone':'Keeping warm'}</span><span>${p.coat?'SHROUD EQUIPPED':'EXPOSED'}</span></div><div class="progress"><span style="width:${Math.round(p.warmth)}%"></span></div></div></div>`;}
function scene(){const w=state.world;return `<section class="scene" aria-label="The Ninth Stratum"><img src="/art/city-noir.webp" alt="Rain-soaked streets beneath colossal server towers and cold neon, watched by hovering civic scanners"><div class="scene-top"><span class="sector">STRATUM IX / REALITY STATUS: DISPUTED</span><span class="scene-weather">${w.temperature}°C · ${e(w.weather)}</span></div><div class="scene-content"><div class="eyebrow">THE CITY HAS TWO VOICES. BOTH KNOW YOUR NAME.</div><h2>THE NINTH STRATUM</h2><p>Rain in your collar. Static in your head.<br>Somewhere above the neon, the Canon is counting.</p></div></section>`;}
function activity(limit=5){return `<div class="journal">${state.log.length?state.log.slice(0,limit).map(l=>`<div class="journal-row"><span class="journal-time">${timeAgo(l.created)}</span><p>${e(l.body)}</p></div>`).join(''):'<div class="journal-empty">Your shift hasn’t started. Neither has your story.</div>'}</div>`;}
function rentPanel(){const p=c(),short=p.rentDebt-p.credits;return `<section class="panel rent-panel"><div class="panel-title">${icon(p.rentDebt?'warning':'check')} ${p.evicted?'EVICTION NOTICE':p.rentDebt?'RENT IS DUE':'RENT SETTLED'}</div><div class="due">${p.rentDebt}<small>CREDITS ${p.rentDebt?'OWED':''}</small></div><p>${p.evicted?'Your bunk was reassigned. Settle your debt to get back inside.':p.rentDebt?'Cell Stack IX, habitation cell 14. Your landlord doesn’t accept excuses.':'A roof over your head. For another day, at least.'}</p><div class="short">${icon(p.rentDebt?'clock':'check')} ${short>0?`${short} credits short`:`Next bill in ${remaining(p.nextRentAt)}`}</div>${short>0?navButton('Find work','jobs','btn primary wide'):p.rentDebt?button('Pay the rent','rent','','primary wide'):navButton('Manage housing','housing','btn ghost wide')}</section>`;}
function pulsePanel(){const w=state.world;return `<section class="panel"><div class="panel-title pulse-title"><span>INTERCEPTED SIGNALS</span><small>LIVE</small></div><div class="notice yellow">${icon('warning')}<div><p>${e(w.event)}</p><small>CANON CIVIC TRANSMISSION</small></div></div><div class="notice">${icon('market')}<div><p>${w.shortage?'The ration printers are failing. Biomass prices have risen.':'The Null Exchange is dispensing biomass. Stock is shared.'}</p><small>NULL EXCHANGE / COMMON SUPPLY</small></div></div><div class="notice">${icon('jobs')}<div><p>The Mnemonic Foundry has vacancies. Some workers returned with someone else’s memories.</p><small>CANON MNEMONIC WORKS</small></div></div></section>`;}
function terminalStatus(){return `<div class="terminal-line"><span><strong>SCHISM.EXE</strong> / CITIZEN SESSION</span><span>${state.totals.citizens} CITIZENS IN REGISTRY</span><span class="online-text">${ready?'[ CONNECTED ]':'[ CONNECTING ]'}</span></div>`;}
function projectPanel(){const project=state.project||{progress:0,target:12,complete:false};const n=project.progress;return `<section class="panel project-panel"><div class="panel-title">[ COLLECTIVE REPAIR ]</div><h3>${project.complete?'The lattice is breathing.':'Restore the thermal lattice.'}</h3><p>${project.complete?'Heat returns to the cell stacks. Every citizen loses 1 less warmth per city hour this city day.':'Twelve relay fragments to restart the thermal lattice. Bodies are cheaper than repairs. The Canon has declined the expense.'}</p><div class="project-bar" aria-label="${n} of 12 relay fragments collected">[${'#'.repeat(n)}${'.'.repeat(12-n)}]</div><div class="project-numbers"><span>${n} / 12 FRAGMENTS</span><span>${project.complete?'RESTORED':'SHARED EFFORT'}</span></div>${button(project.complete?'Heat restored':c().scrap?'Contribute 1 fragment':'Relay fragment needed','contribute','','wide',project.complete||!c().scrap)}<div class="project-note">${project.complete?'Benefit shared by all citizens.':'Each contribution earns 1 trust. Everyone shares the repair.'}<br>A new repair starts each city day.</div></section>`;}
function encounterCard(encounter,art=false){return `<section class="encounter-card"><div class="encounter-top"><span>[ PERSONAL ENCOUNTER ]</span><small>${e(encounter.location.toUpperCase())}</small></div>${art?`<div class="encounter-art"><img src="/art/${encounter.image}.webp" alt="Occult cyberpunk view of ${e(encounter.location)}"></div>`:''}<div class="encounter-body"><div class="encounter-speaker">${e(encounter.speaker.toUpperCase())}</div><h2>${e(encounter.title)}</h2><p class="encounter-copy">${e(encounter.text)}</p><div class="choice-list">${encounter.choices.map((choice,index)=>`<button class="choice" data-choice="${e(choice.id)}" data-thread="${e(encounter.id)}" data-node="${e(encounter.node)}" ${choice.blocked||busy?'disabled':''}><span class="choice-number">[${index+1}]</span><span class="choice-content">${e(choice.label)}<small>${e(choice.preview)}</small>${choice.blocked?`<small class="blocked">${e(choice.blocked)}</small>`:''}</span></button>`).join('')}</div><div class="terminal-prompt">${busy?'WRITING TO REGISTRY...':'SELECT A RESPONSE'} <span>_</span></div></div></section>`;}
/* RESIDENCY */
/* CHARACTER */
/* STREET */
const alignmentLabel=value=>Math.abs(value||0)<8?'UNBOUND':value>0?`ORDER +${value}`:`CHAOS +${Math.abs(value)}`;
function forceMeter(){const f=state.forces;return `<div class="force-labels"><span>ORDER / CANON</span><span>CHAOS / WOUND</span></div><div class="force-meter" role="meter" aria-label="Shared city balance: positive is Order, negative is Chaos" aria-valuemin="-100" aria-valuemax="100" aria-valuenow="${f.balance}"><div class="contested-range"></div><span class="force-needle" style="left:${(100-f.balance)/2}%"></span></div><div class="force-readout"><span>${f.dominance.toUpperCase()}</span><span>${f.balance>0?'+':''}${f.balance} / ${f.interventions} INTERVENTIONS</span></div>`;}
function forcePanel(){const f=state.forces;return `<section class="panel force-panel"><div class="panel-title"><span class="signal-square"></span> [ THE SHARED SIGNAL ]</div><h3>${e(f.title)}</h3>${forceMeter()}<p>${e(f.description)}</p><div class="personal-signal"><span>YOUR ALIGNMENT</span><strong>${alignmentLabel(c().alignment)}</strong></div>${navButton('Order & Chaos','forces','btn wide ghost')}</section>`;}
function forcesPage(){const p=c(),f=state.forces,used=p.lastRiteDay===state.world.day;return `${terminalStatus()}${heading('ORDER IS A CAGE. CHAOS IS A WOUND.','Neither voice will pay your rent. Every citizen can change the balance.')}${banner('city','ONE CITY. TWO POSSIBLE REALITIES.','City influence is shared. Your allegiance is your own.')}<div class="signal-layout">${forcePanel()}<section class="feature-panel"><div class="eyebrow">YOUR IMPLANT / PRIVATE RECORD</div><h2>${alignmentLabel(p.alignment)}</h2><p>The Canon promises a stable reality at the cost of obedience. The Wound offers possibility at the cost of certainty. You can hear both, or disconnect and survive your own life.</p><div class="definition"><span>Implant coherence</span><span>${p.coherence} / 100</span></div><div class="definition"><span>Daily rite</span><span>${used?'RECORDED':'AVAILABLE'}</span></div><p class="help-text">Coherence tracks your implant’s stability. Rites, personal choices, and Somatic Ward treatment change it. Your alignment and story persist; shared city influence resets each six-hour city day.</p>${navButton('Read the next transmission','encounters','btn ghost')}</section></div><div class="section-head"><h2>[ INTERVENE IN THE SIGNAL ]</h2><small>ONE RITE PER CITIZEN / CITY DAY</small></div><div class="cards rite-cards"><article class="job-card canon-card"><div class="job-meta"><span>THE CANON</span><span class="badge">ORDER +12</span></div><div class="rite-sigil" aria-hidden="true">╬</div><h3>Seal a breach.</h3><p>Install a relay fragment where the city has begun to disagree with itself. One version of the world. One count of its inhabitants.</p><div class="job-values"><span>−1 FRAGMENT</span><span>+1 TRUST</span><span>+8 COHERENCE</span><span>1H / −6 ENERGY</span></div>${button(used?'Rite already recorded':!p.scrap?'Relay fragment needed':'Perform the Canon rite','rite','order','primary',used||!p.scrap||p.energy<6)}<p class="rite-effect">When Order reaches +20: rations and broth cost 1 CR less; capture risk rises by 10 percentage points.</p></article><article class="job-card wound-card"><div class="job-meta"><span>THE WOUND</span><span class="badge">CHAOS +12</span></div><div class="rite-sigil" aria-hidden="true">⟁</div><h3>Interrupt the prayer.</h3><p>Break the civic broadcast. Let another voice pass through the neural lattice. Four credits arrive from an address that does not exist.</p><div class="job-values"><span>+4 CR</span><span>+8 HEAT</span><span>−8 COHERENCE</span><span>1H / −6 ENERGY</span></div>${button(used?'Rite already recorded':'Perform the Wound rite','rite','chaos','danger',used||p.energy<6)}<p class="rite-effect">When Chaos reaches −20: food costs 1 CR more; capture risk falls by 10 percentage points; package runs pay 28 CR.</p></article></div><p class="help-text">Personal signal encounters also move the shared balance. The contested range (−19 to +19) uses ordinary food prices and capture risks. Other citizens see your city effects, while your individual decisions remain in your own story.</p>`;}

function overview(){const p=c(),basic=shiftQuote(state.jobs.find(j=>j.id==='sorting'),'standard'),encounter=(state.encounters||[]).find(x=>!x.done&&!x.locked);return `${terminalStatus()}${heading('YOUR BODY IS CITY PROPERTY.','Food, rent, and Revenue. Keep your papers current.')}${identityStrip()}${quickLinks()}${stats()}<div class="overview-grid"><div class="main-column"><div class="overview-scene">${scene()}</div>${encounter?encounterCard(encounter):`<div class="story-summary">${icon('check')}<span>${(state.encounters||[]).every(x=>x.done)?'Your current chapters are complete. Their consequences are still with you.':'No new messages. Work a shift or build trust to open the next encounter.'} ${navButton('Read your story','encounters','text-link')}</span></div>`}<div class="section-head"><h2>[ SURVIVE THE SHIFT ]</h2>${navButton('All work','jobs','text-link')}</div><div class="action-grid"><article class="action-card"><div class="action-symbol">${icon('jobs')}</div><h3>Clock in</h3><p>Sort someone else’s memories.<br>Keep enough of your own.</p><div class="card-detail">+${basic.pay} CR <span class="dim">/ ${basic.hours} HOURS</span></div>${button('Take a shift','work','sorting','primary',!!basic.blocked,'data-shift="standard"')}</article><article class="action-card"><div class="action-symbol">${icon('soup')}</div><h3>Get something hot</h3><p>Empty stomachs make<br>bad decisions.</p><div class="card-detail">${state.goods.find(g=>g.id==='soup').price} CR <span class="dim">/ +35 FULLNESS</span></div>${button('Buy nutrient broth','buy','soup','',p.credits<state.goods.find(g=>g.id==='soup').price||!state.goods.find(g=>g.id==='soup').stock)}</article><article class="action-card"><div class="action-symbol risk">${icon('underground')}</div><h3>Dead neural hardware</h3><p>A missing part.<br>A meal. A risk.</p><div class="card-detail">3 FRAGMENTS <span class="dim">/ RISKY</span></div>${button('Consider it','crime','steal','ghost',p.energy<12)}</article></div><div class="section-head"><h2>[ SESSION LOG ]</h2>${navButton('View journal','profile','text-link')}</div>${activity(4)}</div><aside class="right-column">${rentPanel()}${taxPanel()}${forcePanel()}${projectPanel()}</aside></div>`;}
function personalStory(){const p=c(),encounters=state.encounters||[],available=encounters.filter(x=>!x.done&&!x.locked),locked=encounters.filter(x=>!x.done&&x.locked),decisions=p.story?.decisions||[];return `${terminalStatus()}${heading('YOUR NAME. YOUR CHOICES.','The city belongs to everyone. These moments belong to you.')}<div class="story-tabs"><button class="story-tab ${storyTab==='encounters'?'active':''}" data-story-tab="encounters">Encounters <span class="small-count">${available.length}</span></button><button class="story-tab ${storyTab==='contacts'?'active':''}" data-story-tab="contacts">People you know</button><button class="story-tab ${storyTab==='history'?'active':''}" data-story-tab="history">Past choices</button></div>${storyTab==='encounters'?`<div class="story-grid"><div>${available.length?available.map(x=>encounterCard(x,true)).join(''):`<div class="story-summary">${icon('check')}<span>${encounters.every(x=>x.done)?'These chapters are complete. Your contacts and past choices keep the record.':'No encounter is ready yet. Check the requirements below.'}</span></div>`}${locked.length?'<div class="section-head"><h2>[ LATER IN YOUR STORY ]</h2></div>'+locked.map(x=>`<article class="story-locked"><h3>${e(x.threadTitle)}</h3><p>${e(x.speaker)} / ${e(x.location)}</p><small>${e(x.locked)}</small></article>`).join(''):''}</div><aside><section class="feature-panel"><div class="eyebrow">PERSONAL RECORD</div><h2>They remember.</h2><p>Your responses change relationships, supplies, trust, security interest, and the next chapter. Each decision is saved once.</p><div class="definition"><span>Decisions made</span><span>${decisions.length}</span></div><div class="definition"><span>Chapters resolved</span><span>${encounters.filter(x=>x.done).length} / ${encounters.length}</span></div><p class="help-text">Your story is yours to play alone. The market, district repairs, and citizen board are shared with other players.</p>${navButton('Visit the shared city','city','btn wide ghost')}</section></aside></div>`:storyTab==='contacts'?contactsView():`<section class="feature-panel"><div class="eyebrow">NO REWRITES IN THE REGISTRY</div><h2>What you chose</h2>${decisions.length?decisions.slice().reverse().map(d=>`<article class="decision"><div class="decision-title">${e(d.label)}</div><time>${timeAgo(d.created)}</time><p>${e(d.outcome)}</p></article>`).join(''):'<div class="empty">No decisions recorded. Your first encounter is waiting.</div>'}</section>`}`;}
function contactsView(){const names={iona:['Iona','Your neighbor / Habitation cell 15'],havel:['Havel','Mnemonic overseer'],rook:['Rook','Unlicensed courier'],voss:['Clerk Voss','Canon identity clerk']},contacts=c().story?.contacts||{};return `<section class="feature-panel"><div class="eyebrow">PEOPLE YOU KNOW</div><h2>A familiar face can matter.</h2><p>They’ll remember help, silence, broken promises, and favors. These relationships belong to your story.</p><div class="contact-list">${Object.entries(names).map(([id,[name,role]])=>{const value=contacts[id]||0;return `<div class="contact"><div>${name}<small>${role}</small></div><span class="contact-status" style="color:${value<0?'var(--danger)':value>0?'var(--green)':'var(--muted)'}">${value>=3?'TRUSTS YOU':value>0?'WARMING TO YOU':value<=-2?'DISTRUSTS YOU':value<0?'DISTANT':'UNFAMILIAR'} / ${value>0?'+':''}${value}</span></div>`;}).join('')}</div></section>`;}

function banner(image,title,description){const descriptions={factory:'A dark neural cathedral with suspended storage coffins and biomechanical conduits',market:'Biotech vending shrines beneath a ribbed megastructure, watched by a surveillance drone',city:'Cathedral servers and impossible bridges in the Ninth Stratum'};return `<div class="page-banner"><img src="/art/${image}.webp" alt="${e(descriptions[image]||title)}"><div class="page-banner-content"><h2>${title}</h2><p>${description}</p></div></div>`;}
function work(){const p=c();return `${heading('THE RAIN DOESN’T CLOCK OUT.','Choose a shift. Know what it will take from you.')}${banner('factory','THE MNEMONIC FOUNDRY','Canon Mnemonic Works · Memory is a controlled substance')}<div class="work-options"><div class="shift-types">${Object.entries(state.shiftTypes).map(([id,m])=>`<button class="story-tab ${shiftMode===id?'active':''}" data-shift-mode="${id}">${e(m.name)}${p.shifts<m.requires?' / LOCKED':''}</button>`).join('')}</div><p>${e(state.shiftTypes[shiftMode].description)}</p></div><div class="filter-row"><button class="filter-btn ${filter==='all'?'active':''}" data-filter="all">All shifts</button><button class="filter-btn ${filter==='available'?'active':''}" data-filter="available">Available to you</button><label class="career-filter-label">Track<select id="job-career" aria-label="Filter career path"><option value="all">All careers</option>${state.careers.map(path=>`<option value="${path.id}" ${jobCareer===path.id?'selected':''}>${e(path.name)}</option>`).join('')}</select></label><small>${p.shifts} SHIFTS · ${p.rep} TRUST</small></div><div class="cards">${state.jobs.filter(j=>(jobCareer==='all'||j.career===jobCareer)&&(filter==='all'||!shiftQuote(j).blocked)).map(j=>{const q=shiftQuote(j),locked=!!q.blocked,path=state.careers.find(x=>x.id===j.career);return `<article class="job-card ${locked?'locked':''}">${cityArt(jobArt(j.career),j.name,'job-art')}<div class="job-meta"><span>${e(j.employer)}</span><span class="badge">${e(j.risk.toUpperCase())}</span></div><h3>${e(j.name)}</h3><div class="job-track">${e(path.name)} / ${e(q.name)}</div><p>${e(j.description)}</p><div class="job-values"><span><b>+${q.pay} CR</b></span><span>${q.hours*15} MIN</span><span>−${q.energy} ENERGY</span><span>+${q.xp} XP</span><span>+${j.rep} TRUST</span>${q.scrap?`<span>+${q.scrap} FRAGMENTS</span>`:''}</div><div class="shift-exposure">${q.healthLoss?`−${q.healthLoss} HEALTH · `:''}${q.coherenceLoss?`−${q.coherenceLoss} COHERENCE · `:''}${q.heat?`+${q.heat} HEAT · `:''}−${q.fullness} FULLNESS / −${q.warmth} WARMTH</div>${button(locked?q.blocked:'Accept shift','work',j.id,locked?'ghost':'primary',locked,`data-shift="${shiftMode}"`)}</article>`;}).join('')}</div><p class="help-text">Displayed pay and costs include your loadout, union membership, active career rank, and the district’s heating. ${navButton('Career record','careers','text-link')} ${navButton('Change loadout','loadout','text-link')}</p>${navButton('Rest for six hours','housing')}`;}
function bag(){const p=c();return `<div class="bag"><span class="bag-label">${icon('box')} YOUR BAG</span>${['bread','medicine','scrap'].filter(k=>p[k]).map(k=>`<span class="bag-item">${e(state.goods.find(g=>g.id===k).name)} ×${p[k]} ${k!=='scrap'?button('Use','consume',k,'ghost'):button('Sell 3 CR','sell','','ghost')}</span>`).join('')}${p.coat?'<span class="bag-item">Insulated shroud · equipped</span>':''}${!p.bread&&!p.medicine&&!p.scrap&&!p.coat?'<span class="muted" style="font-size:13px">Empty. Just like your pockets used to be.</span>':''}</div>`;}
function market(){const p=c();return `${heading('Everything has a price.','Food. Warmth. A few more days.')}${banner('market','THE NULL EXCHANGE','Biomass. Blackware. Borrowed identities. · Shared city stock')}<div class="filter-row"><button class="filter-btn ${marketTab==='supply'?'active':''}" data-market="supply">Supply terminals</button><button class="filter-btn ${marketTab==='gear'?'active':''}" data-market="gear">Blackware</button><button class="filter-btn ${marketTab==='players'?'active':''}" data-market="players">Citizen exchange</button><small>${state.world.shortage?'SHORTAGE PRICES IN EFFECT':'CITY SUPPLY OPEN'}</small></div>${bag()}${marketTab==='supply'?`<div class="cards">${state.goods.map(g=>`<article class="good-card"><div class="good-icon">${icon(g.icon)}</div><div class="good-content"><h3>${e(g.name)}</h3><p>${e(g.description)}</p><div class="effect">${e(g.effect)}</div><div class="good-footer"><span>${g.stock} REMAINING</span>${button(!g.stock?'Sold out':g.id==='coat'&&p.ownedGear.includes('coat')?'Equipped':`Buy · ${g.price} CR`,'buy',g.id,'',g.stock===0||p.credits<g.price||(g.id==='coat'&&p.ownedGear.includes('coat')))}</div></div></article>`).join('')}</div><p class="help-text">Rations and stabilizers go into your bag. Broth is consumed immediately. Stock replenishes each city day. Shortages and Order/Chaos control change food prices.</p>`:marketTab==='gear'?gearMarket():exchange()}`;}
function exchange(){const p=c();return `<section class="feature-panel"><div class="eyebrow">BUY FROM YOUR NEIGHBORS</div><h2>Citizen exchange</h2><p>Set your own price. Payment goes directly to the seller; the city can’t take this one.</p><form id="trade-form" class="trade-form"><label>Item<select name="item" aria-label="Item to list">${['scrap','bread','medicine'].map(k=>`<option value="${k}" ${p[k]?'':'disabled'}>${e(state.goods.find(g=>g.id===k).name)} (${p[k]} owned)</option>`).join('')}</select></label><label>Price in credits<input name="price" type="number" min="1" max="50" value="4" required></label><button class="btn primary" ${busy||(!p.scrap&&!p.bread&&!p.medicine)?'disabled':''}>List one item</button></form>${state.listings.length?state.listings.map(l=>`<div class="offer-row">${icon(state.goods.find(g=>g.id===l.item).icon)}<div><h3>${e(state.goods.find(g=>g.id===l.item).name)}</h3><span class="seller">${e(l.name)}${l.seller===p.id?' · Your listing':''}</span></div><span class="offer-price">${l.price} CR</span>${l.seller===p.id?button('Take back','cancel',l.id,'ghost'):button('Buy','trade',l.id,'',p.credits<l.price)}</div>`).join(''):`<div class="empty">${icon('market')}No citizen listings yet. Be the first to trade.</div>`}</section><section class="feature-panel" style="margin-top:20px"><div class="eyebrow">A BUSINESS OF YOUR OWN</div><h2>${p.business?'Your licensed exchange terminal':'From customer to shop owner'}</h2><p>${p.business?'Stock your terminal with rations or relay fragments. A two-hour trading session sells one item to passing city residents: 7 credits for a ration, 8 for a fragment. Two sessions per city day; earnings incur 12% tax. Your citizen exchange now has 12 listing slots.':'A trading license costs 90 credits, 10 trust, one real day of residency, and a cleared ID. Run your own exchange terminal and double your citizen-exchange listing slots.'}</p>${p.business?button('Open the terminal · 2H / −8 energy','business_work','','primary',p.energy<8||(!p.bread&&!p.scrap)):button('Apply for a trading license','business','','',p.credits<90||state.idFlags.length>0||state.requirements.shop.some(([,met])=>!met))}</section>`;}
function housing(){const p=c();return `${heading('Four walls. If you’re lucky.','A place to sleep is a place worth keeping.')}${banner('housing','CELL STACK IX','A bunk and a little distance from the rain')}<div class="two-col"><section class="feature-panel"><div class="eyebrow">YOUR CURRENT ADDRESS</div><h2>${p.evicted?'Beneath the transit lattice':p.housing==='flat'?'Rainline residence, heated apartment 8':p.housing==='room'?'Cell Stack IX, private cell 204':'Cell Stack IX, habitation cell 14'}</h2><p>${p.evicted?'Your identity has been removed from the door. You’re sleeping outside.':p.housing==='flat'?'Heat, running water, and a door that locks.':p.housing==='room'?'A sealed door. A private receiver. Your reflection mostly behaves.':'Six bodies in a habitation cell. No heat. Your wall terminal prays while you sleep.'}</p><div class="definition"><span>Daily rent</span><span>${p.housing==='flat'?32:p.housing==='room'?20:12} credits</span></div><div class="definition"><span>Outstanding rent</span><span>${p.rentDebt} credits</span></div><div class="definition"><span>Next rent bill</span><span>${timeBadge(p.nextRentAt)} in real time</span></div><div class="definition"><span>Rest</span><span>6 city hours / 90 real minutes</span></div><div class="section-head">${button(p.evicted?'Sleep outside':'Get some sleep','rest','','primary')}${button('Settle rent','rent','','',!p.rentDebt||p.credits<p.rentDebt)}</div><p class="help-text">Sleep once per city day. Energy returns during 90 real minutes of rest, and a bunk restores warmth when sleep ends. Hunger and rent continue. Four unpaid bills mean eviction.</p></section><section class="feature-panel"><div class="eyebrow">A LITTLE MORE DIGNITY</div><h2>A room of your own</h2><p>One body. One lock. A mirror with a physical off switch.</p><div class="definition"><span>Deposit</span><span>45 credits</span></div><div class="definition"><span>Daily rent</span><span>20 credits</span></div><p class="help-text">You must settle any eviction before moving in.</p>${button(['room','flat'].includes(p.housing)?'Already home':'Move into a private room','upgrade','','wide',p.credits<45||p.evicted||['room','flat'].includes(p.housing))}</section></div><section class="feature-panel housing-advancement"><div class="eyebrow">ABOVE THE RAINLINE</div><h2>A heated apartment.</h2><p>Less cold exposure and better sleep. Requires a private room, two real days in the city, and 20 trust. Deposit: 180 CR. Rent: 32 CR per city cycle.</p>${button(p.housing==='flat'?'Already home':'Apply for a heated apartment','flat','','',p.housing!=='room'||p.evicted||p.daysInCity<2||p.rep<20||p.credits<180)}</section><div class="section-head"><h2>Own a piece of the city</h2><small>THE SYSTEM HAS ROOM FOR YOU. AT A PRICE.</small></div><section class="feature-panel"><div class="eyebrow">DISTRICT PROPERTY LEASE</div><h2>${p.property?'Your district lease':'Become a landlord'}</h2><p>A transferable lease on a Canon-owned cell stack. Income comes with no promises.</p><div class="job-values"><span>180 CR TO ACQUIRE</span><span>15 TRUST REQUIRED</span><span>9 CR / CITY DAY</span></div>${p.property?button(p.lastCollect===state.world.day?'Collected this city day':'Collect lease income','collect','','primary',p.lastCollect===state.world.day):button('Acquire the lease','property','','',p.credits<180||p.rep<15)}</section>`;}
function underground(){const p=c(),risk=(p.heat/2)+(state.world.inspection?15:0)+(state.world.securityModifier||0)*100+(state.loadoutEffects.captureRisk||0)*100;return `${heading('Some doors aren’t on the map.','The law protects the people who wrote it.')}${banner('market','NO QUESTIONS ASKED','Below the Null Exchange · Disable your implant microphone')}<section class="criminal-rank"><span class="eyebrow">UNDERGROUND REPUTATION</span><h2>${p.criminal.xp>=60?'District fixer':p.criminal.xp>=24?'Known runner':p.criminal.xp>=9?'Street contact':'Nobody knows you yet.'}</h2><p>${p.criminal.xp} XP / ${p.criminal.successes} successful operations. Three attempts per city day. Unreported crime income avoids Revenue, but arrests flag your ID and carry a sentence. The underground pulls your alignment toward Chaos.</p></section><div class="heat-box">${icon('shield')}<div>Security interest: <strong>${p.heat<20?'Low':p.heat<50?'Noticed':'Under watch'}</strong><br>Your record makes every checkpoint riskier.</div><small>${Math.round(p.heat)} / 100 HEAT</small></div><div class="cards"><article class="job-card"><div class="job-meta"><span>MNEMONIC FOUNDRY / DEAD LATTICE</span><span class="badge">${Math.max(0,Math.min(100,30+risk))}% CAPTURE RISK</span></div><h3>Steal relay fragments</h3><p>There is a blind interval between two sentinel prayers. Three relay fragments. One missing memory.</p><div class="job-values"><span><b>3 FRAGMENTS</b></span><span>1H · −12 ENERGY</span><span>FAILURE: UP TO −7 CR</span></div>${button('Take the risk','crime','steal','danger',p.energy<12)}</article><article class="job-card"><div class="job-meta"><span>WESTERN CHECKPOINT</span><span class="badge">${Math.max(0,Math.min(100,40+risk))}% CAPTURE RISK</span></div><h3>Run a sealed package</h3><p>Don’t open it. Don’t remember the address. Don’t get stopped.</p><div class="job-values"><span><b>+${state.world.contrabandPay||24} CR</b></span><span>3H · −22 ENERGY</span><span>FAILURE: UP TO −15 CR</span></div>${button('Accept the package','crime','smuggle','danger',p.energy<22)}</article></div><div class="section-head"><h2>The fragment broker</h2></div><section class="feature-panel"><p>A buyer with no name pays 3 credits per piece. Your bag holds ${p.scrap} relay fragments.</p>${button('Sell one fragment · 3 CR','sell','','',p.scrap<1)}</section>${casinoPanel()}<p class="help-text">Failure adds heat, costs health, and lowers trust. Heat fades while you’re away. Inspections add 15 percentage points to capture risk. Order adds 10; Chaos subtracts 10.</p>`;}
function institutions(){const p=c();return `${heading('Take a number. Take a seat.','The city has a process for everything. Helping you is optional.')}${banner('registry','CANON REGISTRY','Work permits, taxes, and the right to be counted')}${bureau()}<div class="cards"><article class="job-card"><div class="job-meta"><span>SOMATIC WARD / BIOLOGICAL SERVICES</span><span class="badge">WALK-INS ACCEPTED</span></div><h3>Somatic recalibration</h3><p>A surgical arm repairs the body attached to your implant. The waiting room has no clocks.</p><div class="job-values"><span><b>8 CR</b></span><span>+40 HEALTH · +15 COHERENCE</span><span>1H WAIT</span></div>${button('Get treatment','clinic','','',p.credits<8)}</article><article class="job-card"><div class="job-meta"><span>CANON IDENTITY ARCHIVE</span><span class="badge">DISCRETION ADVISED</span></div><h3>A missing file</h3><p>The clerk can make your security record a little less interesting. Cash only.</p><div class="job-values"><span><b>12 CR</b></span><span>−35 SECURITY HEAT</span></div>${button('Pay the clerk','bribe','','',p.credits<12||!p.heat)}</article><article class="job-card"><div class="job-meta"><span>THE UNCOUNTED / WORKERS’ MUTUAL</span><span class="badge">${p.union?'MEMBER':'YOU’RE NOT ALONE'}</span></div><h3>Stand together</h3><p>The union collects a little from everyone. A collective contract pays members 1 extra credit per shift.</p><div class="job-values"><span><b>4 CR DUES</b></span><span>${state.totals.members||0} MEMBERS</span><span>+1 CR / SHIFT</span></div>${p.union?button('Organize a shift · 2H','organize','','',p.energy<12):button('Join the union','union','','primary',p.credits<4)}</article><article class="job-card"><div class="job-meta"><span>CANON ORDINATION OFFICE</span><span class="badge">CIVIC CAREER / 2 DAYS RESIDENCY</span></div><h3>The other side of the desk</h3><p>You can spend your life waiting in line. Or become the person calling the numbers.</p><div class="job-values"><span><b>60 CR APPLICATION</b></span><span>MUNICIPAL OFFICIAL</span></div>${button(p.official?'Post secured':'Apply for a municipal post','official','','',p.credits<60||p.official||state.idFlags.length>0||state.requirements.administrative.some(([,met])=>!met))}${p.official?button('Process work permits · +17 CR','official_work','','primary',p.energy<8):''}</article></div>`;}
function board(){return `<section class="board"><div class="board-head"><h2>The neighborhood board</h2><span class="eyebrow">CITIZEN NOTICES</span></div><form class="notice-form" id="notice-form"><textarea name="body" maxlength="240" minlength="3" required placeholder="Looking for work? Trading supplies? Leave a note for your neighbors." aria-label="Your citizen notice">${e(drafts.notice)}</textarea><button class="btn primary" ${busy?'disabled':''}>Pin a notice</button></form>${state.board.length?state.board.map(p=>`<article class="board-post"><div class="post-meta">${icon('user')}<b>${e(p.name)}</b><span class="post-role">${e(p.role)}</span><time>${timeAgo(p.created)}</time></div><p>${e(p.body)}</p></article>`).join(''):'<div class="empty">The board is bare. Someone has to speak first.</div>'}</section>`;}
function city(){return `${terminalStatus()}${heading('THE CITY KEEPS MOVING.','Every citizen shares the market, the weather, and the work left unfinished.')}<div class="world-summary"><span><b>${state.totals.citizens}</b> REGISTERED CITIZENS</span><span><b>${state.totals.members||0}</b> UNION MEMBERS</span><span>WORLD DAY <b>${state.world.day}</b></span></div>${scene()}${areaGallery()}${cityEvents()}<div class="section-head"><h2>[ SOMETHING WE CAN CHANGE ]</h2></div><div class="two-col">${forcePanel()}${projectPanel()}</div>${pulsePanel()}<div class="section-head"><h2>Know your way around</h2><small>CITY DAY ${state.world.day}</small></div><div class="cards"><article class="job-card"><div class="job-meta"><span>SECTOR 02</span><span class="badge">MNEMONIC</span></div><h3>Mnemonic Foundry</h3><p>Your past is sorted, licensed, and sold here. They pay you to handle someone else’s.</p>${navButton('Find a shift','jobs','btn primary')}</article><article class="job-card"><div class="job-meta"><span>SECTOR 04</span><span class="badge">TRADE</span></div><h3>Null Exchange</h3><p>Vending shrines dispense biomass. A masked courier sells directions to doors that were never built.</p>${navButton('Visit the market','market')}</article><article class="job-card"><div class="job-meta"><span>SECTOR 04</span><span class="badge">RESIDENTIAL</span></div><h3>Cell Stack IX</h3><p>Your rent buys a little space between you and the weather.</p>${navButton('Go home','housing')}</article><article class="job-card"><div class="job-meta"><span>SECTOR 01</span><span class="badge">AUTHORITY</span></div><h3>The Canon Registry</h3><p>The Canon keeps one version of every citizen. Revisions require a fee.</p>${navButton('Visit the offices','institutions')}</article></div>${board()}`;}
function citizens(){const p=c();return `${heading('You aren’t the only one.','Everyone here is trying to get through another week.')}<div class="filter-row"><span class="eyebrow">${state.totals.citizens} REGISTERED CITIZEN${state.totals.citizens===1?'':'S'}</span><small>${state.totals.members||0} UNION MEMBERS</small></div><table class="people-table"><thead><tr><th>CITIZEN</th><th>OCCUPATION</th><th>TRUST</th><th>SHIFTS</th></tr></thead><tbody>${state.citizens.length?state.citizens.map(person=>`<tr><td class="${person.id===p.id?'your-name':''}">${e(person.name)}${person.id===p.id?'<span class="small-badge">YOU</span>':''}</td><td>${e(person.role)}</td><td>${person.rep}</td><td>${person.shifts}</td></tr>`).join(''):'<tr><td colspan="4">The registry is connecting.</td></tr>'}</tbody></table><p class="help-text">The 30 most recently active citizens. Trade supplies through the citizen exchange, or leave a note on the neighborhood board.</p>${board()}`;}
function profile(){const p=c();return `${heading('Your citizen papers.','A number to the city. A life to you.')}<div class="two-col"><section class="feature-panel"><div class="eyebrow">CANON BIOLOGICAL REGISTRY</div><div class="profile-heading"><div class="profile-avatar">${icon('user')}</div><div><h2>${e(p.name)}</h2><p>${e(p.role)} · NINTH STRATUM</p></div></div><form class="name-form" id="name-form"><input name="name" value="${e(drafts.name||p.name)}" minlength="2" maxlength="24" aria-label="Citizen name" required><button class="btn">Update papers</button></form><div class="definition"><span>Citizen ID</span><span>${e(p.id.slice(0,8).toUpperCase())}</span></div><div class="definition"><span>Shifts completed</span><span>${p.shifts}</span></div><div class="definition"><span>Employer trust</span><span>${p.rep}</span></div><div class="definition"><span>Signal alignment</span><span>${alignmentLabel(p.alignment)}</span></div><div class="definition"><span>Implant coherence</span><span>${p.coherence} / 100</span></div><div class="definition"><span>Fullness</span><span>${p.fullness} / 100</span></div><div class="definition"><span>Security heat</span><span>${Math.round(p.heat)} / 100</span></div><div class="definition"><span>Personal time</span><span>Day ${Math.floor(p.clock/24)+1} · ${String(p.clock%24).padStart(2,'0')}:00</span></div><div class="definition"><span>Union</span><span>${p.union?'Member':'Unaffiliated'}</span></div></section><section class="feature-panel"><div class="eyebrow">THERE’S MORE THAN ONE WAY UP</div><h2>Find your place</h2><p>Every door has a cost. Some take money; others take a piece of you.</p><div class="role-paths"><div class="role-path"><b>Trusted worker</b><small>8 trust · Licensed lattice work</small></div><div class="role-path"><b>Smuggler</b><small>Complete a package run</small></div><div class="role-path"><b>Union organizer</b><small>Join, then organize a shift</small></div><div class="role-path"><b>Shop owner</b><small>10 trust · 90 CR license</small></div><div class="role-path"><b>Landlord</b><small>15 trust · 180 CR lease</small></div><div class="role-path"><b>Canon official</b><small>20 trust · 60 CR application</small></div></div><div class="quote">You are not the chosen one.<br>You are the one who showed up again.</div></section></div>${bag()}<div class="section-head"><h2>Your journal</h2><small>THE REGISTRY REMEMBERS</small></div>${activity(12)}`;}
const pages={overview,city,jobs:work,market,housing,underground,institutions,citizens,profile:residencyProfile,encounters:personalStory,forces:forcesPage,loadout,inventory,careers,street:streetPage,workshop:workshopPage,network:networkPage};
function render(){
  if(!pages[tab])tab='overview';
  $('#navigation').innerHTML=`<div class="nav-group">SURVIVE THE CITY</div>${tabs.slice(0,5).map(([id,label])=>`<button class="nav-button ${tab===id?'active':''}" data-nav="${id}" ${tab===id?'aria-current="page"':''}><span class="nav-key" aria-hidden="true">[${String(tabs.findIndex(t=>t[0]===id)+1).padStart(2,'0')}]</span> ${label}${id==='jobs'?`<span class="nav-count" aria-hidden="true">${state.jobs.filter(j=>!shiftQuote(j,'standard').blocked).length}</span>`:''}</button>`).join('')}<div class="nav-group">FIND YOUR PLACE</div>${tabs.slice(5).map(([id,label])=>`<button class="nav-button ${tab===id?'active':''}" data-nav="${id}" ${tab===id?'aria-current="page"':''}><span class="nav-key" aria-hidden="true">[${String(tabs.findIndex(t=>t[0]===id)+1).padStart(2,'0')}]</span> ${label}</button>`).join('')}`;
  $('#citizen-name').textContent=c().name;$('#citizen-role').textContent=c().role;$('#avatar').innerHTML=citizenArt(c().appearance,true);
  $('#breadcrumb').textContent=tab==='overview'?'CITIZEN OVERVIEW':tab==='profile'?'CITIZEN PAPERS':(tabs.find(x=>x[0]===tab)?.[1]||tab).toUpperCase();
  $('#city-clock').textContent=`DAY ${String(state.world.day).padStart(3,'0')} / ${String(state.world.hour).padStart(2,'0')}:00`;
  $('#top-weather').textContent=`${state.world.temperature}°C · ${state.world.weather}`;
  document.body.classList.toggle('onboarding',!ready||!c().registered);
  $('#main').innerHTML=`${connection?`<div class="connection-banner"><span>${e(connection)}</span>${!ready&&connection.includes('Sign in')?'<a href="/signin-with-chatgpt?return_to=%2F" target="_top">Sign in</a>':'<button class="btn ghost" data-refresh>Retry</button>'}</div>`:''}${!ready||!c().registered?arrivalPage():arrivalConfirmation()+assignmentPanel()+shortTaskPanel()+papersWarning()+pages[tab]()}`;
  $('#save-status').textContent=busy?'Saving to the city registry…':ready?'PROGRESS SAVED · CITY CONNECTED':'Connecting to the city registry…';
}
function toast(message,error=false){clearTimeout(toastTimer);const el=$('#toast');el.textContent=message;el.className=`toast-visible ${error?'error':''}`;toastTimer=setTimeout(()=>el.className='',6000);}
function go(dest){if(!pages[dest])return;tab=dest;if(location.hash!=='#'+dest)history.pushState({},'','#'+dest);render();window.scrollTo({top:0,behavior:'instant'});$('.sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}
function modal(title,body,action=null){pendingAction=action;$('#dialog-content').innerHTML=`<div class="modal-body"><button class="modal-close" data-close aria-label="Close dialog">${icon('close')}</button><div class="eyebrow">${action?'A CHOICE WITH CONSEQUENCES':'CITIZEN FIELD GUIDE'}</div><h2>${title}</h2>${body}<div class="modal-actions"><button class="btn ghost" data-close>${action?'Back':'Understood'}</button>${action?'<button class="btn primary" data-confirm>Confirm</button>':''}</div></div>`;$('#dialog').showModal();}
function confirmAction(action,id,mode='standard'){const p=c();if(!ready){modal('Claim your citizen papers.',`<p>Sign in to enter the city and keep your progress across visits.</p><p style="margin-top:20px"><a class="btn primary" href="/signin-with-chatgpt?return_to=%2F" target="_top">Sign in with ChatGPT</a></p>`);return;}
  if(action==='work'){const j=state.jobs.find(j=>j.id===id),q=shiftQuote(j,mode);modal(j.name,`<p>${e(j.description)}</p><div class="modal-facts"><div class="definition"><span>Shift</span><span>${e(q.name)}</span></div><div class="definition"><span>Pay / career XP</span><span>+${q.pay} CR / +${q.xp} XP</span></div><div class="definition"><span>Time / energy</span><span>${q.hours*15} real minutes / −${q.energy}</span></div><div class="definition"><span>Fullness / warmth</span><span>−${q.fullness} / −${q.warmth}</span></div>${q.healthLoss?`<div class="definition"><span>Hazard damage</span><span>−${q.healthLoss} health</span></div>`:''}${q.coherenceLoss?`<div class="definition"><span>Implant coherence</span><span>−${q.coherenceLoss}</span></div>`:''}${q.heat?`<div class="definition"><span>Security heat</span><span>+${q.heat}</span></div>`:''}${q.scrap?`<div class="definition"><span>Recovered fragments</span><span>+${q.scrap}</span></div>`:''}</div><p>One city hour is 15 real minutes. Pay and XP arrive when the shift finishes. Eight work hours per city day; earned pay incurs 12% tax. The rent won’t wait.</p>`,{action,id,shift:mode});}
  else if(action==='rite'){modal(id==='order'?'Seal a breach.':'Interrupt the prayer.',`<p>${id==='order'?'Consume one relay fragment. Gain 1 trust and 8 coherence. Move your alignment and the shared city 12 points toward Order.':'Gain 4 credits and 8 security heat. Lose 8 coherence. Move your alignment and the shared city 12 points toward Chaos.'}</p><p>Costs 1 hour and 6 energy. One rite per city day.</p>`,{action,id});}
  else if(action==='tax'){modal('Revenue does not forget.',`<p>Pay ${p.taxDebt} CR of earned-income tax. ${p.taxHold?'This pays your debt. Visit the Registry afterward to clear your flagged ID.':'Your ID stays current when you pay before the deadline.'}</p>`,{action,id});}
  else if(action==='clearance'){modal('Take a number.',`<p>${p.credits>=2?'A 2 CR fee, 6 energy, and 15 real minutes.':'An indigence appeal: 14 energy and 30 real minutes.'} Factory access returns after the review finishes. Your taxes must be paid and security heat at most 20.</p>`,{action,id});}
  else if(action==='crime'){const risk=Math.max(0,Math.min(100,(id==='steal'?30:40)+p.heat/2+(state.world.inspection?15:0)+(state.world.securityModifier||0)*100+(state.loadoutEffects.captureRisk||0)*100));modal(id==='steal'?'Nobody’s watching. Probably.':'A package. A checkpoint.',`<p>${id==='steal'?'Three relay fragments could mean a meal. Getting caught means a fine, injuries, and a face security remembers.':`Deliver the mnemonic package and earn ${state.world.contrabandPay||24} credits. Get caught and lose up to 15 credits, health, and trust.`}</p><div class="modal-facts"><div class="definition"><span>Capture risk</span><span>${risk}%</span></div><div class="definition"><span>Energy</span><span>−${id==='steal'?12:22}</span></div><div class="definition"><span>Time</span><span>${id==='steal'?1:3} hours</span></div></div>`,{action,id});}
  else if(['upgrade','flat','business','property','official'].includes(action)){const titles={flat:'Heat above the rainline.',upgrade:'A door of your own.',business:'Your own exchange terminal.',property:'Become the landlord.',official:'An official appointment.'};const copy={flat:'Pay a 180-credit deposit for a heated apartment. Rent is 32 credits per city cycle.',upgrade:'Pay a 45-credit deposit. Your daily rent rises to 20 credits.',business:'Pay 90 credits for a licensed exchange terminal and become a shop owner. Requires 10 trust, one real day in the city, and a cleared ID.',property:'Pay 180 credits for a district lease. Collect 9 credits each city day. Requires 15 trust.',official:'Pay the 60-credit processing fee. Become a municipal official. Requires two real days, 25 trust, 80 civic XP, and a cleared ID.'};modal(titles[action],`<p>${copy[action]}</p>`,{action,id});}
  else send({action,id}).catch(()=>{});
}
async function send(input){if(busy)return;if(!ready){confirmAction(input.action,input.id);return;}busy=true;render();
  try{const r=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});const result=await r.json();if(!r.ok)throw new Error(result.error||'The registry is unavailable.');state=result;stateReceivedAt=Date.now();connection='';if(input.action==='register'){arrivalNotice=true;tab='overview';history.replaceState({},'','#overview');}if(input.action==='post')drafts.notice='';if(input.action==='rename')drafts.name='';toast(result.message);}
  catch(err){toast(err.message,true);if(err.message.includes('changed'))await load(true);throw err;}
  finally{busy=false;render();}return {citizen:state.citizen,message:state.message};
}
async function load(show=true){if(busy&&!show)return;try{const r=await fetch('/api/state');const result=await r.json();if(!r.ok){if(r.status===401){connection='Sign in to enter the city and keep your progress.';ready=false;render();return;}throw new Error(result.error||'The city registry is unavailable.');}state=result;stateReceivedAt=Date.now();ready=true;connection='';render();}catch(err){connection=err.message||'The city registry is unreachable. Try again in a moment.';render();}}
document.addEventListener('click',event=>{const el=event.target.closest('button,[data-nav]');if(!el)return;if(el.matches('[data-nav]')){if(el.dataset.marketSwitch)marketTab=el.dataset.marketSwitch;go(el.dataset.nav);}else if(el.matches('[data-inventory]')){inventoryFilter=el.dataset.inventory;render();}else if(el.matches('[data-shift-mode]')){shiftMode=el.dataset.shiftMode;render();}else if(el.matches('[data-career-jobs]')){jobCareer=el.dataset.careerJobs;go('jobs');}else if(el.matches('[data-story-tab]')){storyTab=el.dataset.storyTab;render();}else if(el.matches('[data-choice]')){if(!ready)confirmAction('encounter','');else send({action:'encounter',id:el.dataset.thread,node:el.dataset.node,choice:el.dataset.choice}).catch(()=>{});}else if(el.matches('[data-action]'))confirmAction(el.dataset.action,el.dataset.id||'',el.dataset.shift||'standard');else if(el.matches('[data-close]')){$('#dialog').close();pendingAction=null;}else if(el.matches('[data-confirm]')&&pendingAction){const action=pendingAction;pendingAction=null;$('#dialog').close();send(action).catch(()=>{});}else if(el.matches('[data-filter]')){filter=el.dataset.filter;render();}else if(el.matches('[data-market]')){marketTab=el.dataset.market;render();}else if(el.matches('[data-refresh]'))load();else if(el.matches('[data-help]'))modal('Survive the district.',`<p>You arrive by train with zero credits and no allegiance. Sign-in keeps one durable character. Appearance is cosmetic.</p><ul><li><b>Shared time:</b> one city hour is 15 real minutes; one city cycle is six real hours. Work and sleep never fast-forward it. Days in the city count real 24-hour days since registration.</li><li><b>Work:</b> eight hours per city day. Pay, XP, and district production arrive at completion. Sleep once per day; idle time recovers some energy.</li><li><b>Short tasks:</b> 20–75 seconds; ten per city cycle. Spend energy to scavenge, decode signals, craft practical supplies, and accept network contracts. Work-break tasks fit into a shift.</li><li><b>Survival:</b> hunger, cold, rent, and tax deadlines continue offline. Four unpaid rent bills mean eviction. A daily emergency meal keeps a broke citizen from being trapped.</li><li><b>Revenue:</b> 12% of reported earnings is owed as tax. Pay it yourself. Missing the deadline flags your ID and closes factory gates. Debt payment and Registry clearance are separate steps.</li><li><b>Crime:</b> three attempts per city day. Unreported money avoids tax; success builds underground reputation and moves you toward Chaos. Arrests carry fines, detention, and an ID hold.</li><li><b>City events:</b> production and freight affect food and stock, organizing wins higher wages, crime triggers lockdowns, and boiler crews improve warmth for everyone.</li><li><b>Progression:</b> shop permits require a day of residence. Administration needs two days and civic training. Security needs seven days, 30 shifts, 60 trust, 180 civic XP, and Order +40.</li></ul>`);});
document.addEventListener('submit',event=>{const form=event.target;if(!['notice-form','name-form','trade-form'].includes(form.id))return;event.preventDefault();if(!form.reportValidity())return;const d=new FormData(form);if(form.id==='notice-form')send({action:'post',body:d.get('body')}).catch(()=>{});if(form.id==='name-form')send({action:'rename',name:d.get('name')}).catch(()=>{});if(form.id==='trade-form')send({action:'list',id:d.get('item'),price:Number(d.get('price'))}).catch(()=>{});});
$('#menu-toggle').innerHTML=icon('menu');$('.help-button').innerHTML=icon('help');$('#menu-toggle').addEventListener('click',()=>{const open=$('.sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));});
document.addEventListener('click',event=>{if(innerWidth<=760&&$('.sidebar').classList.contains('open')&&!event.target.closest('.sidebar')&&!event.target.closest('#menu-toggle')){$('.sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
window.addEventListener('popstate',()=>{tab=location.hash.slice(1)||'overview';render();});
$('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){$('#dialog').close();pendingAction=null;}});
document.addEventListener('input',event=>{if(event.target.closest('#notice-form'))drafts.notice=event.target.value;if(event.target.closest('#name-form'))drafts.name=event.target.value;});
render();load();setInterval(()=>{if(ready&&!busy&&!$('#dialog').open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&document.visibilityState==='visible')load(false);},30000);
// Structured access to the same visible city journeys, when the browser supports it.
const modelContext=document.modelContext;
if(modelContext?.registerTool){const lifetime=new AbortController();
  const register=tool=>{try{Promise.resolve(modelContext.registerTool(tool,{signal:lifetime.signal})).catch(()=>{});}catch{}};
  register({name:'read_citizen_state',description:'Read your saved citizen, city conditions, inventory, jobs, and shared market.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async()=>{await load();if(!ready)throw new Error('Sign in to enter the city.');return {citizen:state.citizen,world:state.world,goods:state.goods,jobs:state.jobs};}});
  register({name:'navigate_city',description:'Open a city screen without performing a gameplay action.',inputSchema:{type:'object',properties:{screen:{type:'string',enum:Object.keys(pages)}},required:['screen'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:input=>{if(!input||!pages[input.screen])throw new Error('Unknown city screen.');go(input.screen);return {screen:tab};}});
  register({name:'complete_shift',description:'Start a timed job assignment. Pay and XP arrive at completion; consumes energy and daily work hours.',inputSchema:{type:'object',properties:{job:{type:'string',enum:['sorting','hauling','cleaning','maintenance']}},required:['job'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async input=>{if(!input||!state.jobs.some(j=>j.id===input.job))throw new Error('Unknown job.');if(!ready)throw new Error('Sign in to enter the city.');return send({action:'work',id:input.job});}});
  window.addEventListener('pagehide',()=>lifetime.abort(),{once:true});
}

document.addEventListener('keydown',event=>{if(event.altKey||event.ctrlKey||event.metaKey||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||$('#dialog').open)return;if(/^[1-3]$/.test(event.key)){const choice=document.querySelectorAll('.choice')[Number(event.key)-1];if(choice&&!choice.disabled){event.preventDefault();choice.click();}}});

document.addEventListener('change',event=>{if(event.target.id==='job-career'){jobCareer=event.target.value;render();}});
